<?php
if(!defined('ABSPATH')){exit;}
final class AICS_Content_Image_Insertion_Service{
	public function __construct(private ?AICS_Featured_Image_Ownership_Service $ownership=null){$this->ownership=$ownership??new AICS_Featured_Image_Ownership_Service();}
	public function insert(string $content,array $article,array $settings,string $alt):array{$placement=sanitize_key((string)($settings['content_image']['placement']??'disabled'));if('disabled'===$placement||empty($settings['content_image']['enabled'])){return array('success'=>true,'content'=>$content,'status'=>'disabled','placement'=>'disabled','warning'=>'');}$attachment=absint($article['featured_image_attachment_id']??0);if(!$attachment||!wp_attachment_is_image($attachment)){return array('success'=>false,'code'=>'content_image_attachment_missing','content'=>$content);}$owned=$this->ownership->validate_attachment($attachment,$article);if(empty($owned['success'])){return array('success'=>false,'code'=>'content_image_ownership_invalid','content'=>$content);}if(str_contains($content,'wp-image-'.$attachment)||preg_match('/<!--\s*wp:image\s+\{"id":'.$attachment.'[,}]/',$content)){return array('success'=>true,'content'=>$content,'status'=>'existing','placement'=>$placement,'warning'=>'');}$html=wp_get_attachment_image($attachment,'large',false,array('class'=>'wp-image-'.$attachment,'alt'=>$alt));if(''===$html){return array('success'=>false,'code'=>'content_image_insertion_failed','content'=>$content);}$block='<!-- wp:image {"id":'.$attachment.',"sizeSlug":"large","linkDestination":"none","className":"aics-content-featured-image"} -->' . "\n" . '<figure class="wp-block-image size-large aics-content-featured-image">'.$html.'</figure>' . "\n" . '<!-- /wp:image -->';[$offset,$actual]=$this->offset($content,$placement);$warning=$actual===$placement?'':'content_image_placement_fallback';$enhanced=substr($content,0,$offset)."\n\n".$block."\n\n".substr($content,$offset);return array('success'=>true,'content'=>$enhanced,'status'=>'inserted','placement'=>$actual,'warning'=>$warning,'attachment_id'=>$attachment);}
	private function offset(string $content,string $placement):array{preg_match_all('/<p\b[^>]*>.*?<\/p>/is',$content,$p,PREG_OFFSET_CAPTURE);$paragraphs=$p[0]??array();$fallback=$paragraphs?($paragraphs[0][1]+strlen($paragraphs[0][0])):strlen($content);if('before_first_h2'===$placement&&preg_match('/<h2\b/i',$content,$m,PREG_OFFSET_CAPTURE)){return array($m[0][1],$placement);}if('after_first_h2'===$placement&&preg_match('/<h2\b[^>]*>.*?<\/h2>\s*(<p\b[^>]*>.*?<\/p>)/is',$content,$m,PREG_OFFSET_CAPTURE)){return array($m[1][1]+strlen($m[1][0]),$placement);}if('middle'===$placement&&$paragraphs){$i=(int)floor((count($paragraphs)-1)/2);return array($paragraphs[$i][1]+strlen($paragraphs[$i][0]),$placement);}if('after_introduction'===$placement&&$paragraphs){$words=0;foreach($paragraphs as $para){$words+=count(preg_split('/\s+/u',wp_strip_all_tags($para[0]),-1,PREG_SPLIT_NO_EMPTY)?:array());if($words>=150){return array($para[1]+strlen($para[0]),$placement);}}return array($fallback,'after_introduction');}return array($fallback,'after_introduction');}
}
